const SEGMENT_OPTIONS = [
  { value: "concert", label: ja.pitch.concert },
  { value: "hornF", label: ja.pitch.hornF },
] as const;

function SegmentedFixture({
  value,
  disabled,
}: {
  value: "concert" | "hornF";
