/**
 * Import flow controller (UI-020 / issue #25; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * Framework-free: App subscribes to state + screen events; tests drive it
 * with fake ports. The controller owns the §27 import-side transitions —
 *
 *   EMPTY ─pick/drop→ OPENING_AUDIO ─ok→ AUDIO_READY
 *                         ├─ unsupported/corrupt → AUDIO_ERROR ─閉じる→ EMPTY
 *                         └─ (audio already loaded: error surfaces as a
 *                             dialog issue over the kept workspace)
 *   recent project ─→ OPENING_AUDIO ─source ok→ AUDIO_READY
 *                         └─ path/hash failure → SOURCE_MISSING
 *                                └─ 音源を指定 → hash ok → AUDIO_READY
 *                                                mismatch → SOURCE_MISSING
 *
 * Error policy (§20): state what failed, what is kept, the next action —
 * a failed re-import never destroys a loaded audio session, and the source
 * file is only ever read (FND-001: identity = content hash, not location).
 */
import type { ScreenState } from "../workspace/screen";
import { ja } from "../strings/ja";
import { type ImportPorts } from "./ports";
import { audioFormatOf, baseName, projectDisplayName } from "./formats";
import { recordRecentProject, loadRecentProjects } from "./recentProjects";
import type {
  AudioFileRef,
  AudioFormat,
  ImportIssue,
  LoadedAudio,
  ProjectSummary,
  RecentProjectEntry,
  RecordedAudioRef,
  SourceMissingInfo,
} from "./types";

export type ImportPhase =
  "idle" | "opening" | "ready" | "error" | "sourceMissing";

export interface ImportState {
  readonly phase: ImportPhase;
  /** File/project name shown while `phase === "opening"`. */
  readonly openingLabel: string | null;
  /** "audio" | "project" selects the loading copy variant. */
  readonly openingKind: "audio" | "project" | null;
  readonly audio: LoadedAudio | null;
  /** Recoverable failure — card content on AUDIO_ERROR, dialog content
      when the workspace already has audio (the error never destroys it). */
  readonly issue: ImportIssue | null;
  readonly sourceMissing: SourceMissingInfo | null;
}

export const INITIAL_IMPORT_STATE: ImportState = {
  phase: "idle",
  openingLabel: null,
  openingKind: null,
  audio: null,
  issue: null,
  sourceMissing: null,
};

export interface ImportEvents {
  /** Screen transitions owned by the import flow (§27). */
  onScreenChange(screen: ScreenState): void;
  /** Mirrors state for React consumers. */
  onState(state: ImportState): void;
  /** aria-live status bar announcements (role="status"). */
  announce(message: string): void;
  /** Recent-projects list changed (persisted + UI). */
  onRecentChange(entries: readonly RecentProjectEntry[]): void;
  /** Decoded audio is ready — host wires it into the transport adapter. */
  onAudioReady(audio: LoadedAudio): void;
  /** Optional (#106): the opened project carried a saved score — the
   *  host restores it and jumps to SCORE_READY instead of waiting for
   *  a re-transcription. Fires after the usual state/screen updates. */
  onProjectScoreReady?(
    result: unknown,
    project: {
      projectId: string;
      sourceHash: string | null;
      // #265: the recorded source path — the host keeps it so a
      // SOURCE_MISSING save preserves the relink target.
      sourcePath: string | null;
    },
  ): void;
  /** Optional (#264): a project document was opened (or relinked) —
   *  fires before onAudioReady so the host can restore the saved
   *  transcription settings into 採譜オプション before the audio
   *  slot resets them to global defaults. */
  onProjectOpened?(project: ProjectSummary): void;
}

type RecentStorage = Pick<Storage, "getItem" | "setItem"> | null;

export class ImportController {
  private state: ImportState = INITIAL_IMPORT_STATE;
  /** Serialization guard: a superseded open (user re-picked mid-load) must
      not overwrite newer state when it resolves late. */
  private generation = 0;

  constructor(
    private readonly ports: ImportPorts,
    private readonly events: ImportEvents,
    private readonly storage: RecentStorage = null,
  ) {}

  getState(): ImportState {
    return this.state;
  }

  /** `file.openAudio` (Ctrl+O / 開く / drop fallback): pick then import. */
  async openViaDialog(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // A picker failure is not a file error — surface the generic
      // open-failure issue rather than an unhandled rejection.
      this.fail({ kind: "openFailed" });
      return;
    }
    if (!ref) return; // cancel is silent — not an error
    await this.importRefs([ref]);
  }

  /**
   * Drag&drop / dialog entry point. With several files the first supported
   * one wins (single-document app); zero supported → honest format error.
   */
  async importRefs(refs: readonly AudioFileRef[]): Promise<void> {
    if (refs.length === 0) return;
    // A dropped/picked .hornscribe.json is a project open, not an audio
    // import — the dialog's "all files" escape hatch can hand one over.
    const projRef = refs.find((r) => r.name.endsWith(".hornscribe.json"));
    if (projRef) {
      const bytes = projRef.kind === "file" ? projRef.file : undefined;
      await this.openProject(
        {
          name: projectDisplayName(projRef.name),
          path: projRef.kind === "path" ? projRef.path : "",
          openedAt: Date.now(),
        },
        bytes,
      );
      return;
    }
    const ref = refs.find((r) => audioFormatOf(r.name) !== null) ?? refs[0];
    const format = audioFormatOf(ref.name);
    if (format === null) {
      this.fail({ kind: "unsupported", fileName: ref.name });
      return;
    }
    await this.importAudioRef(ref, format);
  }

  /**
   * FEAT-001 (#60): 録音バッファを直接取り込む(PC音源/マイク録音)。
   * `ref` は `kind:"recording"` で、`blob` は WAV または MediaRecorder
   * 出力(ブラウザ dev)。拡張子は常に `.wav`/`.webm` を仮定するため
   * `audioFormatOf` の allowlist を迂回して良い(録音由来なので形式は
   * 自明)。失敗時は openFailed に落とす。
   */
  async importRecording(ref: RecordedAudioRef): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      // Tauri 録音は保存済みファイルを読む(#70: 実ファイル=リリンク可能)。
      const blob = ref.blob ?? (await this.ports.readAudioBytes(ref.path!));
      const contentHash = ref.path
        ? await this.ports.sha256Hex(blob)
        : undefined;
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        // 録音物は decode 可能なコンテナなので拡張子は実質 wav。
        format: "wav",
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(
        ref.source === "loopback"
          ? `PCの音を取り込みました(${ref.name})`
          : `録音を取り込みました(${ref.name})`,
      );
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /** OPENING_AUDIO → AUDIO_READY, or AUDIO_ERROR. */
  private async importAudioRef(
    ref: AudioFileRef,
    format: AudioFormat,
  ): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      const blob = await this.blobFor(ref);
      // #243: the content hash is the source identity (FND-001) —
      // computing it once at import lets project save write a real
      // contentHash instead of the empty string that broke reopen.
      const contentHash = await this.ports.sha256Hex(blob);
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(ja.import.feedback.loaded(ref.name));
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /**
   * 最近使ったプロジェクト → verify the recorded source path (store.py
   * `verify_source_audio`: exists + content hash) → AUDIO_READY, else
   * SOURCE_MISSING with the relink action.
   * `bytes` carries a browser-dev File ref (no durable path — the
   * project is opened but not recorded in the recents list).
   */
  async openProject(entry: RecentProjectEntry, bytes?: Blob): Promise<void> {
    const gen = this.begin("project", entry.name);
    try {
      const blob = bytes ?? (await this.ports.readProjectBytes(entry.path));
      // Browser-dev File refs have no durable path — project.path
      // stays "" so touchRecent skips them; the display name comes
      // from the file name instead.
      const project = parseProjectFile(
        await blob.arrayBuffer(),
        entry.path,
        entry.path ? undefined : entry.name,
      );
      if (!this.isCurrent(gen)) return;
      if (!project.sourcePath || !project.sourceHash) {
        this.enterSourceMissing(project, false);
        return;
      }
      let audioBlob: Blob;
      try {
        audioBlob = await this.ports.readAudioBytes(project.sourcePath);
      } catch {
        if (!this.isCurrent(gen)) return;
        this.enterSourceMissing(project, false);
        return;
      }
      const hash = await this.ports.sha256Hex(audioBlob);
      if (!this.isCurrent(gen)) return;
      if (hash !== project.sourceHash) {
        // File at the recorded path exists but content differs —
        // store.py treats this like a moved source (verify fails).
        this.enterSourceMissing(project, false);
        return;
      }
      try {
        const decoded = await this.ports.decodeAudio(audioBlob, entry.name);
        if (!this.isCurrent(gen)) return;
        this.finishProjectOpen(
          project,
          {
            kind: "path",
            path: project.sourcePath,
            name: baseName(project.sourcePath),
          },
          audioBlob,
          decoded,
        );
      } catch {
        if (!this.isCurrent(gen)) return;
        this.fail({
          kind: "openFailed",
          fileName: baseName(project.sourcePath),
        });
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "projectOpenFailed", fileName: entry.name });
    }
  }

  /** SOURCE_MISSING: 「音源を指定」 — pick a candidate then verify. */
  async pickRelinkSource(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // Picker failure while relinking — stay on the SOURCE_MISSING card
      // and say what happened; the user can retry 音源を指定.
      this.events.announce(ja.import.errors.openFailedBody);
      return;
    }
    if (!ref) return;
    await this.relinkWith(ref);
  }

  /**
   * Hash-based relink, the same contract as
   * `ProjectStore.relink_source_audio`: the candidate must hash to the
   * recorded content hash — identity is content, not location.
   */
  async relinkWith(ref: AudioFileRef): Promise<void> {
    const sm = this.state.sourceMissing;
    if (!sm) return;
    const gen = this.begin("project", sm.project.name);
    try {
      const blob = await this.blobFor(ref);
      const hash = await this.ports.sha256Hex(blob);
      if (!this.isCurrent(gen)) return;
      if (hash !== sm.project.sourceHash) {
        this.enterSourceMissing(sm.project, true);
        return;
      }
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const format = audioFormatOf(ref.name) ?? "wav";
      const audio: LoadedAudio = {
        // #234: carry the verified hash so the audio identity matches
        // the project's recorded sourceHash — a relinked source
        // keeps its restored score instead of invalidating it.
        ref: { ...ref, contentHash: sm.project.sourceHash ?? hash },
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.touchRecent(sm.project);
      // #264: relink resumes the same project — restore its saved
      // 採譜 settings before the audio slot resets options.
      this.events.onProjectOpened?.(sm.project);
      this.events.onAudioReady(audio);
      // #106: the project's saved score (already restored in the
      // background) can now land — the relinked audio matches the
      // recorded content hash.
      if (sm.project.scoreResult != null) {
        this.events.onProjectScoreReady?.(sm.project.scoreResult, {
          projectId: sm.project.projectId,
          sourceHash: sm.project.sourceHash,
          sourcePath: sm.project.sourcePath,
        });
        this.events.announce(ja.import.feedback.projectOpened(sm.project.name));
      } else {
        this.events.announce(ja.import.feedback.sourceRelinked);
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      // Candidate unreadable or undecodable after a hash match — stay on
      // the missing-source card; the status line carries what happened
      // (the card itself already offers the retry action).
      this.enterSourceMissing(sm.project, false);
      this.events.announce(ja.import.errors.openFailedBody);
    }
  }

  /** 閉じる on AUDIO_ERROR / SOURCE_MISSING → EMPTY; on a kept workspace
      (issue dialog over audio) it only clears the issue. */
  dismiss(): void {
    if (this.state.phase === "error" || this.state.phase === "sourceMissing") {
      this.setState({ ...INITIAL_IMPORT_STATE });
      return;
    }
    if (this.state.issue) {
      this.setState({ ...this.state, issue: null });
    }
  }

  /** Recent entries (host renders them in the EMPTY state). */
  recentProjects(): RecentProjectEntry[] {
    return loadRecentProjects(this.storage);
  }

  /* ----------------------------- internals ----------------------------- */

  private begin(kind: "audio" | "project", label: string): number {
    const gen = ++this.generation;
    this.setState({
      phase: "opening",
      openingLabel: label,
      openingKind: kind,
      audio: this.state.audio,
      issue: null,
      sourceMissing: null,
    });
    return gen;
  }

  private isCurrent(gen: number): boolean {
    return gen === this.generation;
  }

  private fail(issue: ImportIssue): void {
    if (this.state.audio) {
      // Workspace is alive — the issue becomes a dialog over it, the
      // loaded audio/waveform/transport all stay (§20 "what is kept").
      this.setState({ ...this.state, phase: "ready", issue });
    } else {
      this.setState({
        phase: "error",
        openingLabel: null,
        openingKind: null,
        audio: null,
        issue,
        sourceMissing: null,
      });
    }
  }

  private enterSourceMissing(project: ProjectSummary, mismatch: boolean): void {
    this.setState({
      phase: "sourceMissing",
      openingLabel: null,
      openingKind: null,
      audio: null,
      issue: null,
      sourceMissing: { project, mismatch },
    });
    // #106: the score survives a missing/moved source — restore it
    // now; the audio can be relinked afterwards.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult, {
        projectId: project.projectId,
        sourceHash: project.sourceHash,
        sourcePath: project.sourcePath,
      });
    }
  }

  private finishProjectOpen(
    project: ProjectSummary,
    ref: AudioFileRef,
    blob: Blob,
    decoded: {
      durationSeconds: number;
      sampleRate: number;
      peaks: readonly number[];
    },
  ): void {
    const format = audioFormatOf(ref.name) ?? "wav";
    const audio: LoadedAudio = {
      // #234: the recorded project hash is this audio's verified
      // content identity — carry it so identity checks line up.
      ref: { ...ref, contentHash: project.sourceHash ?? undefined },
      fileName: ref.name,
      format,
      sizeBytes: blob.size,
      durationSeconds: decoded.durationSeconds,
      sampleRate: decoded.sampleRate,
      peaks: decoded.peaks,
      mediaSource: { kind: "blob", blob },
    };
    this.setState({
      phase: "ready",
      openingLabel: null,
      openingKind: null,
      audio,
      issue: null,
      sourceMissing: null,
    });
    this.touchRecent(project);
    // #264: restore the saved 採譜 settings before the host's audio
    // slot logic runs — 採譜し直す must default to the conditions
    // that produced this project, not current global defaults.
    this.events.onProjectOpened?.(project);
    this.events.onAudioReady(audio);
    // #106: a project saved with score extras skips re-transcription —
    // the host restores the document and lands on SCORE_READY.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult, {
        projectId: project.projectId,
        sourceHash: project.sourceHash,
        sourcePath: project.sourcePath,
      });
      this.events.announce(ja.import.feedback.projectOpened(project.name));
    } else {
      this.events.announce(ja.import.feedback.loaded(ref.name));
    }
  }

  private touchRecent(project: ProjectSummary): void {
    // A project opened from browser bytes has no durable path — the
    // recents list only records entries that can actually be reopened.
    if (!project.path) return;
    const list = recordRecentProject(
      { name: project.name, path: project.path },
      this.storage,
    );
    this.events.onRecentChange(list);
  }

  private async blobFor(ref: AudioFileRef): Promise<Blob> {
    return ref.kind === "file" ? ref.file : this.ports.readAudioBytes(ref.path);
  }

  private setState(next: ImportState): void {
    this.state = next;
    this.events.onState(next);
    const screen = screenForPhase(next.phase);
    if (screen) this.events.onScreenChange(screen);
  }
}

/** The screen states the import flow drives; "ready" is the last one it
    owns — later transitions belong to the transcription/score features. */
function screenForPhase(phase: ImportPhase): ScreenState | null {
  switch (phase) {
    case "idle":
      return "empty";
    case "opening":
      return "openingAudio";
    case "ready":
      return "audioReady";
    case "error":
      return "audioError";
    case "sourceMissing":
      return "sourceMissing";
  }
}

/* --------------------------- project parsing --------------------------- */

/**
 * Parse a `.hornscribe.json` document into the relink-relevant summary
 * (schema v1 — mirrors `HornScribeProject.from_dict`). Throws on malformed
 * or unsupported documents → caller maps to `projectOpenFailed`.
 */
export function parseProjectFile(
  bytes: ArrayBuffer,
  path: string,
  displayName?: string,
): ProjectSummary {
  const data = JSON.parse(new TextDecoder().decode(bytes)) as Record<
    string,
    unknown
  >;
  if (typeof data !== "object" || data === null) {
    throw new Error("project document is not an object");
  }
  if (data.schemaVersion !== 1) {
    throw new Error(`unsupported schemaVersion: ${String(data.schemaVersion)}`);
  }
  if (typeof data.projectId !== "string" || data.projectId === "") {
    throw new Error("projectId is missing or malformed");
  }
  const source = data.sourceAudio as Record<string, unknown> | null;
  return {
    path,
    projectId: data.projectId,
    name: displayName ?? projectDisplayName(path),
    sourcePath:
      source && typeof source.originalPath === "string"
        ? source.originalPath
        : null,
    sourceHash:
      source && typeof source.contentHash === "string"
        ? source.contentHash
        : null,
   scoreResult: scoreResultFromProject(data),
    transcriptionSettings: transcriptionSettingsFromProject(data),
  };
}

/**
 * Reassemble the completed-job `result` shape from the project's saved
 * extras (#106). `engineDocumentFromResult` and `scoreHandoffFromResult`
 * consume this directly — the score is restored without re-transcribing.
 * Returns null when the file carries no MusicXML (externally authored
 * projects keep the AUDIO_READY-only open path).
 */
function scoreResultFromProject(
  data: Record<string, unknown>,
): Record<string, unknown> | null {
  const concert = data.musicXmlConcert;
  const horn = data.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") {
    return null;
  }
  const score = data.score as Record<string, unknown> | null;
  return {
    musicXmlConcert: concert,
    musicXmlHornF: horn,
    scoreRevision:
      score && typeof score.revision === "string"
        ? score.revision
        : "rev-project",
    reviewIssues: Array.isArray(data.reviewIssues) ? data.reviewIssues : [],
    scoreDocument: data.scoreDocument ?? null,
    meta: data.meta ?? {},
  };
}

/** #264: `transcription.settings` echo from the project file — the
 *  authoritative provenance of the conditions that produced the
 *  score. Unknown/malformed values stay raw here; the options mapper
 *  (transcriptionParams) validates them into UI state. */
function transcriptionSettingsFromProject(
  data: Record<string, unknown>,
): Record<string, unknown> | null {
  const record = data.transcription as Record<string, unknown> | null;
  const settings = record?.settings;
  if (typeof settings !== "object" || settings === null) return null;
  return settings as Record<string, unknown>;
}

/** #264: project transcription.settings -> 採譜オプション restore mapping. */
import { describe, expect, it } from "vitest";
import { transcriptionOptionsFromSettings } from "./transcriptionParams";
import { DEFAULT_TRANSCRIPTION_OPTIONS } from "./types";

describe("transcriptionOptionsFromSettings", () => {
  it("restores the full engine settings echo", () => {
    const o = transcriptionOptionsFromSettings({
      tempoBpm: 96,
      meter: "6/8",
      minDurationQl: "1/8",
      triplets: "always",
      simplicity: "detailed",
      range: "selection",
      selectionStartSec: 12.5,
      selectionEndSec: 40,
      backend: "basicPitch",
      texture: "melody",
    });
    expect(o).toEqual({
      tempo: "manual",
      tempoBpm: 96,
      meter: "6/8",
      // 1/8 ql = 32分音符
      minDuration: "32",
      triplets: "allow",
      simplicity: "detailed",
      range: "selection",
      texture: "melody",
      backend: "basicPitch",
      selectionStartSec: 12.5,
      selectionEndSec: 40,
    });
  });

  it("maps engine triplet policy names to UI values", () => {
    expect(
      transcriptionOptionsFromSettings({ triplets: "never" }).triplets,
    ).toBe("none");
    expect(
      transcriptionOptionsFromSettings({ triplets: "auto" }).triplets,
    ).toBe("auto");
  });

  it("minDurationQl fractions map to UI denominators", () => {
    expect(
      transcriptionOptionsFromSettings({ minDurationQl: "1/2" }).minDuration,
    ).toBe("8");
    expect(
      transcriptionOptionsFromSettings({ minDurationQl: "1/4" }).minDuration,
    ).toBe("16");
    // A value outside the UI's three choices falls back to default.
    expect(
      transcriptionOptionsFromSettings({ minDurationQl: "1/64" }).minDuration,
    ).toBe(DEFAULT_TRANSCRIPTION_OPTIONS.minDuration);
  });

  it("auto tempo (null tempoBpm) restores the auto mode", () => {
    const o = transcriptionOptionsFromSettings({ tempoBpm: null });
    expect(o.tempo).toBe("auto");
    expect(o.tempoBpm).toBeNull();
  });

  it("unknown/newer values fall back to defaults per key", () => {
    const o = transcriptionOptionsFromSettings({
      meter: "13/16",
      texture: "orchestral",
      backend: "demucs-v9",
      triplets: "sometimes",
      minDurationQl: "abc",
      futureKey: true,
    });
    expect(o.meter).toBe("auto");
    expect(o.texture).toBe("auto");
    expect(o.backend).toBe("auto");
    expect(o.triplets).toBe("auto");
    expect(o.minDuration).toBe(DEFAULT_TRANSCRIPTION_OPTIONS.minDuration);
  });

  it("null settings yield the defaults", () => {
    expect(transcriptionOptionsFromSettings(null)).toEqual(
      DEFAULT_TRANSCRIPTION_OPTIONS,
    );
  });
});

/**
 * Build the `job.start` params for the real `transcription` job kind
 * (ENG-002) from the loaded audio + the 採譜オプション popover state.
 *
 * Wire contract (python/hornscribe/transcription/options.py):
 * `audioPath` is required — the engine reads the file itself, so only
 * refs backed by a real path can drive a real job:
 *
 * - `kind:"path"` (native dialog / native drop) -> the path itself;
 * - `kind:"recording"` with `path` (Tauri capture: the WAV was already
 *   persisted under appDataDir/recordings/) -> that path;
 * - `kind:"file"` (browser dev drop) and pathless recordings -> staged
 *   first via stageAudioForEngine (#86): the dev bridge writes the bytes
 *   under %TEMP%/hornscribe-dev and the returned path is passed in as
 *   `stagedAudioPath`, which wins over every ref-derived path. When the
 *   bridge is unreachable staging returns null and the mock engine
 *   ignores params anyway, so dev sessions still exercise the flow.
 *
 * `tempoBpm` is only sent for manual tempo — auto omits it so the
 * engine runs beat tracking. `range:"selection"` sends the user's
 * start/end seconds, clamped to the clip duration.
 */
import type {
  AudioFileRef,
  LoadedAudio,
  RecordedAudioRef,
  TranscriptionOptions,
} from "./types";
import { DEFAULT_TRANSCRIPTION_OPTIONS } from "./types";

function audioPathOf(ref: AudioFileRef | RecordedAudioRef): string | null {
  if (ref.kind === "path") return ref.path;
  if (ref.kind === "recording") return ref.path ?? null;
  return null; // kind === "file": browser dev, no on-disk source
}

export interface TranscriptionJobParams {
  audioPath?: string;
  tempoBpm?: number;
  meter?: string;
  minDuration?: string;
  triplets?: string;
  simplicity?: string;
  range?: string;
  selectionStartSec?: number;
  selectionEndSec?: number;
  backend?: string;
  texture?: string;
}

export function buildTranscriptionParams(
  audio: LoadedAudio | null,
  options: TranscriptionOptions,
  stagedAudioPath: string | null = null,
  backend: string | null = null,
): TranscriptionJobParams {
  const params: TranscriptionJobParams = {};
  const path = stagedAudioPath ?? (audio ? audioPathOf(audio.ref) : null);
  if (path) params.audioPath = path;

  // #108/#189: the engine pin reaches the job. A per-job override
  // (options.backend) wins over the global 設定→詳細設定 choice.
  const resolvedBackend =
    options.backend && options.backend !== "auto"
      ? options.backend
      : backend;
  if (resolvedBackend && resolvedBackend !== "auto") {
    params.backend = resolvedBackend;
  }

  if (options.tempo === "manual" && options.tempoBpm != null) {
    params.tempoBpm = options.tempoBpm;
  }
  // "auto" meter is the engine default; only pin an explicit choice.
  if (options.meter && options.meter !== "auto") {
    params.meter = options.meter;
  }
  if (options.minDuration) params.minDuration = options.minDuration;
  if (options.triplets !== "auto") params.triplets = options.triplets;
  if (options.simplicity !== "standard") {
    params.simplicity = options.simplicity;
  }
  // "auto" is the engine default; pin mono/melody explicitly so the
  // choice is recorded in the job settings echo.
  if (options.texture !== "auto") params.texture = options.texture;
  if (options.range === "selection") {
    params.range = "selection";
    // The engine requires end > start for selection mode; clamp the
    // user's seconds into [0, duration] and fall back to the full span
    // when the pair is empty or inverted.
    const dur = audio?.durationSeconds ?? 0;
    let start = options.selectionStartSec ?? 0;
    let end = options.selectionEndSec ?? dur;
    start = Math.min(Math.max(start, 0), dur);
    end = Math.min(Math.max(end, 0), dur);
    if (end <= start) {
      start = 0;
      end = dur;
    }
    params.selectionStartSec = start;
    params.selectionEndSec = end;
  }
  return params;
}

/* ------------------------- #264 project settings ------------------------- */

/** Engine `settings_dict()` keys -> 採譜オプション state. The saved
 *  echo is authoritative provenance: on project open the popover is
 *  restored to the conditions that produced the score, so 採譜し直す
 *  reproduces them instead of silently using current global defaults.
 *  Unknown/newer values fall back to DEFAULT per key. */
export function transcriptionOptionsFromSettings(
  settings: Record<string, unknown> | null | undefined,
): TranscriptionOptions {
  const s = settings ?? {};
  const pick = <T extends string>(
    key: string,
    allowed: readonly T[],
    fallback: T,
  ): T => {
    const v = s[key];
    return typeof v === "string" && (allowed as readonly string[]).includes(v)
      ? (v as T)
      : fallback;
  };
  const num = (key: string): number | null => {
    const v = s[key];
    return typeof v === "number" && Number.isFinite(v) ? v : null;
  };

  const tempoBpm = num("tempoBpm");
  // UI denominators are note values (16th = 1/4 ql); the engine echo
  // stores quarter-length fractions ("1/4"). Only the three UI
  // choices are restorable — anything else falls back to default.
  const minDuration = (() => {
    const raw = s["minDurationQl"];
    if (typeof raw !== "string") return DEFAULT_TRANSCRIPTION_OPTIONS.minDuration;
    const m = /^(\d+)\s*\/\s*(\d+)$/.exec(raw.trim());
    if (!m) return DEFAULT_TRANSCRIPTION_OPTIONS.minDuration;
    const ql = Number(m[1]) / Number(m[2]);
    if (!(ql > 0)) return DEFAULT_TRANSCRIPTION_OPTIONS.minDuration;
    const denom = Math.round(4 / ql);
    return denom === 8 || denom === 16 || denom === 32
      ? String(denom)
      : DEFAULT_TRANSCRIPTION_OPTIONS.minDuration;
  })();

  const tripletsRaw = pick("triplets", ["auto", "always", "never"] as const, "auto");
  return {
    ...DEFAULT_TRANSCRIPTION_OPTIONS,
    tempo: tempoBpm != null ? "manual" : "auto",
    tempoBpm,
    meter: pick(
      "meter",
      ["auto", "2/4", "3/4", "4/4", "5/4", "6/8", "7/8", "9/8", "12/8"] as const,
      "auto",
    ),
    minDuration,
    // Engine values are the TripletPolicy names; the popover speaks
    // allow/none/auto (always <-> allow, never <-> none).
    triplets:
      tripletsRaw === "always" ? "allow" : tripletsRaw === "never" ? "none" : "auto",
    simplicity: pick("simplicity", ["standard", "simple", "detailed"] as const, "standard"),
    range: pick("range", ["all", "selection"] as const, "all"),
    texture: pick("texture", ["auto", "mono", "melody", "voices", "chords"] as const, "auto"),
    backend: pick("backend", ["auto", "basicPitch", "pyin"] as const, "auto"),
    // Selection seconds are source-relative; keep them verbatim so a
    // restored 範囲指定 re-runs over the same span of the same audio.
    selectionStartSec: num("selectionStartSec"),
    selectionEndSec: num("selectionEndSec"),
  };
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string; contentHash?: string }
  | { kind: "file"; file: File; name: string; contentHash?: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
  /** Saved job-result extras (#106): when the file carries
   *  musicXmlConcert/musicXmlHornF + score.revision + reviewIssues,
   *  this mirrors the completed-job `result` payload so the score can
   *  be restored without re-transcribing. Null for projects without
   *  saved score data (externally authored files). */
 scoreResult: unknown | null;
  /** #264: the saved `transcription.settings` echo (provenance). The
   *  host restores it into 採譜オプション so 採譜し直す reruns under
   *  the conditions that produced this project, not the current
   *  global defaults. Null for externally authored files. */
  transcriptionSettings: Record<string, unknown> | null;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
  /** 音源の種類 — mono=単旋律楽器, melody=メロディ優先(ミックス/JPOP),
      auto=重なりの多さからエンジンが自動判定。 */
  texture: "auto" | "mono" | "melody" | "voices" | "chords";
  /** #189: per-job engine override. "auto" inherits the global
   *  設定→詳細設定 backend; an explicit choice pins this job only. */
  backend: "auto" | "basicPitch" | "pyin";
  /** 範囲指定時の開始/終了（秒）。null = 音声の端まで。 */
  selectionStartSec: number | null;
  selectionEndSec: number | null;
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "auto",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
  texture: "auto",
  backend: "auto",
  selectionStartSec: null,
  selectionEndSec: null,
};

/**
 * @vitest-environment jsdom
 *
 * UI-070 §13 error-recovery gate: every error surface must offer a visible,
 * keyboard-reachable recovery action — never a dead end (issue acceptance:
 * "all error-recovery fixtures have non-dead-end actions"). Renders each
 * surface with its real components and asserts:
 *
 * - at least one enabled actionable button exists;
 * - the surface announces itself (role=alert or a named region);
 * - a dismiss/close path exists (focusable, enabled);
 * - no raw stack-trace style copy (no "Error:" / hex dumps).
 */

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it } from "vitest";
import { ImportScreenBody, type ImportView } from "../import/ImportStates";
import {
  DEFAULT_TRANSCRIPTION_OPTIONS,
  type LoadedAudio,
} from "../import/types";
import { TranscriptionErrorView } from "../components/TranscriptionErrorView";
import type { FailureKind } from "../sidecar";
import type { ScreenState } from "../workspace/screen";

(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;

let root: Root | null = null;
let host: HTMLDivElement | null = null;

const NOOP = () => undefined;

const AUDIO: LoadedAudio = {
  ref: { kind: "path", path: "C:\\audio\\take-03.wav", name: "take-03.wav" },
  fileName: "take-03.wav",
  format: "wav",
  sizeBytes: 14_680_064,
  durationSeconds: 197.8,
  sampleRate: 44_100,
  peaks: [0.2, 0.5, 0.8, 0.4],
  mediaSource: { kind: "blob", blob: new Blob() },
};

function view(overrides: Partial<ImportView>): ImportView {
  return {
    audio: null,
    openingLabel: null,
    openingKind: null,
    issue: null,
    sourceMissing: null,
    recentProjects: [],
    options: DEFAULT_TRANSCRIPTION_OPTIONS,
    onOpenAudio: NOOP,
    onOpenProject: NOOP,
    onPickRelink: NOOP,
    onDismissError: NOOP,
    onOptionsChange: NOOP,
    ...overrides,
  };
}

async function render(node: React.ReactElement): Promise<void> {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(node);
  });
}

afterEach(async () => {
  if (root) {
    await act(async () => {
      root!.unmount();
    });
  }
  root = null;
  host?.remove();
  host = null;
  document.body.innerHTML = "";
});

function enabledButtons(): HTMLButtonElement[] {
  return [...document.querySelectorAll<HTMLButtonElement>("button")].filter(
    (b) => !b.disabled,
  );
}

const STACK_TRACE_RE = /\b(Error|Exception|Traceback)\b.*:|0x[0-9a-fA-F]{6,}|\bat \w+\.[jt]s/;

describe("error-recovery surfaces (§13)", () => {
  const importCases: { name: string; screen: ScreenState; v: ImportView }[] = [
    {
      name: "audioError — unsupported codec",
      screen: "audioError",
      v: view({ issue: { kind: "unsupported", fileName: "memo.txt" } }),
    },
    {
      name: "audioError — read failure",
      screen: "audioError",
      v: view({ issue: { kind: "openFailed", fileName: "take-03.wav" } }),
    },
    {
      name: "audioError — project open failure",
      screen: "audioError",
      v: view({
        issue: { kind: "projectOpenFailed", fileName: "etude.hornscribe.json" },
      }),
    },
    {
      name: "sourceMissing — source moved",
      screen: "sourceMissing",
      v: view({
        sourceMissing: {
          project: {
            path: "C:\\music\\etude.hornscribe.json",
            projectId: "p1",
            name: "etude",
            sourcePath: "C:\\audio\\etude.flac",
            sourceHash: "a1b2c3",
            scoreResult: null,
            transcriptionSettings: null,
          },
          mismatch: false,
        },
      }),
    },
    {
      name: "sourceMissing — hash mismatch",
      screen: "sourceMissing",
      v: view({
        sourceMissing: {
          project: {
            path: "C:\\music\\etude.hornscribe.json",
            projectId: "p1",
            name: "etude",
            sourcePath: "C:\\audio\\etude.flac",
            sourceHash: "a1b2c3",
            scoreResult: null,
            transcriptionSettings: null,
          },
          mismatch: true,
        },
      }),
    },
  ];

  it.each(importCases)("$name has a non-dead-end action set", async ({ screen, v }) => {
    await render(
      <ImportScreenBody screen={screen} view={v} onTranscribe={NOOP} />,
    );
    const buttons = enabledButtons();
    expect(buttons.length).toBeGreaterThanOrEqual(1);
    // The surface announces itself.
    expect(document.querySelector('[role="alert"]')).not.toBeNull();
    // Copy must not leak a raw stack trace.
    const text = document.body.textContent ?? "";
    expect(STACK_TRACE_RE.test(text)).toBe(false);
  });

  const failures: FailureKind[] = [
    "transcriptionFailed",
    "workerCrashed",
    "workerNotResponding",
  ];

  it.each(failures)(
    "transcription error surface (%s) offers retry/restart + diagnostics + close",
    async (kind) => {
      await render(
        <TranscriptionErrorView
          kind={kind}
          restarting={false}
          diagnostics={() => "diagnostic text"}
          onPrimary={NOOP}
          onClose={NOOP}
        />,
      );
      const buttons = enabledButtons();
      // Primary recovery + diagnostics + close = at least 3 actions.
      expect(buttons.length).toBeGreaterThanOrEqual(3);
      expect(document.querySelector('[role="alert"]')).not.toBeNull();
      const text = document.body.textContent ?? "";
      expect(STACK_TRACE_RE.test(text)).toBe(false);
    },
  );

  it("audioReady keeps the workspace live (transcribe action present)", async () => {
    await render(
      <ImportScreenBody
        screen="audioReady"
        view={view({ audio: AUDIO })}
        onTranscribe={NOOP}
      />,
    );
    expect(enabledButtons().length).toBeGreaterThanOrEqual(1);
  });
});

/**
 * Inspector view-model tests (UI-030). All Japanese text is produced in
 * score/inspector.ts via a copy deck — these tests pin the model shape the
 * PropertiesPanel renders.
 */
import { describe, expect, it } from "vitest";
import {
  buildNoteInspector,
  buildScoreInspector,
  headlinePitch,
  keyLabelJa,
  type InspectorCopy,
} from "./inspector";
import type { ParsedNote } from "./scoreDoc";
import type { ScoreReviewIssue } from "./review";

const copy: InspectorCopy = {
  review: {
    reasonTitle: (r) => `title:${r}`,
    reasonDetail: (i) => `detail:${i.reason}`,
    severityLabel: (s) => `sev:${s}`,
    statusLabel: (s) => `status:${s}`,
  },
  measure: (n) => `第${n}小節`,
  scoreSeconds: (sec) => `スコア ${sec.toFixed(1)} 秒`,
  tieFragments: (n) => `タイで分割（${n}分割）`,
  tempo: (bpm) => `${bpm} BPM`,
  measureCount: (n) => `${n} 小節`,
  noteCount: (n) => `${n} 音`,
  openIssues: (n) => `${n} 件`,
  key: (fifths, mode) => keyLabelJa(fifths, mode),
};

const note = (over: Partial<ParsedNote>): ParsedNote => ({
  exportId: "hs-sn-000001",
  canonicalId: "sn-000001",
  isRest: false,
  chord: false,
  measure: 1,
  dots: 0,
  tied: false,
  ...over,
});

describe("buildScoreInspector", () => {
  it("summarizes the document for the nothing-selected state", () => {
    const model = buildScoreInspector(
      {
        title: "Test Piece",
        tempoBpm: 100,
        meter: "4/4",
        keyFifths: -1,
        keyChanges: [],
        keyMode: null,
        swingFeel: false,
        omittedIssueCount: 0,
        measureCount: 12,
        noteCount: 40,
      },
      3,
      copy,
    );
    expect(model.kind).toBe("score");
    expect(model.tempoLabel).toBe("100 BPM");
    expect(model.meterLabel).toBe("4/4");
    expect(model.keyLabel).toBe("ヘ長調");
    expect(model.measureLabel).toBe("12 小節");
    expect(model.noteLabel).toBe("40 音");
    expect(model.openIssueLabel).toBe("3 件");
  });

  it("shows key transitions when the piece modulates (#146)", () => {
    const model = buildScoreInspector(
      {
        title: "Modulating Piece",
        tempoBpm: 100,
        meter: "4/4",
        keyFifths: 0,
        keyChanges: [
          { measure: 1, fifths: 0, mode: null },
          { measure: 17, fifths: -5, mode: null },
        ],
        keyMode: null,
        swingFeel: false,
        omittedIssueCount: 0,
        measureCount: 32,
        noteCount: 100,
      },
      0,
      copy,
    );
    expect(model.keyLabel).toBe("ハ長調 → 変ニ長調（第17小節）");
  });

  it("labels minor keys with the minor name (#252)", () => {
    const model = buildScoreInspector(
      {
        title: "Minor Piece",
        tempoBpm: 100,
        meter: "4/4",
        keyFifths: 0,
        keyChanges: [{ measure: 1, fifths: 0, mode: "minor" }],
        keyMode: "minor",
        swingFeel: false,
        omittedIssueCount: 0,
        measureCount: 8,
        noteCount: 20,
      },
      0,
      copy,
    );
    expect(model.keyLabel).toBe("イ短調");
  });

  it("projects signatures +1 fifth in the written horn view (#270)", () => {
    const meta = {
      title: "Horn Piece",
      tempoBpm: 100,
      meter: "4/4",
      keyFifths: -1,
      keyChanges: [],
      keyMode: null,
      swingFeel: false,
      omittedIssueCount: 0,
      measureCount: 8,
      noteCount: 20,
    };
    const concert = buildScoreInspector(meta, 0, copy, "concert");
    const horn = buildScoreInspector(meta, 0, copy, "hornF");
    expect(concert.keyLabel).toBe("ヘ長調");
    expect(horn.keyLabel).toBe("ハ長調");
    expect(horn.keyFifths).toBe(0);
    // Fold: concert +7 (嬰ハ長調) writes as -4 (変イ長調).
    const sharp = buildScoreInspector({ ...meta, keyFifths: 7 }, 0, copy, "hornF");
    expect(sharp.keyFifths).toBe(-4);
    expect(sharp.keyLabel).toBe("変イ長調");
  });
});

describe("buildNoteInspector", () => {
  const concert = [
    note({
      exportId: "hs-sn-000012",
      canonicalId: "sn-000012",
      step: "C",
      octave: 4,
      type: "quarter",
      measure: 4,
    }),
    note({
      exportId: "hs-sn-000012-2",
      canonicalId: "sn-000012",
      step: "C",
      octave: 4,
      type: "whole",
      measure: 5,
      tied: true,
    }),
  ];
  const written = [
    note({
      exportId: "hs-sn-000012",
      canonicalId: "sn-000012",
      step: "G",
      octave: 4,
      type: "quarter",
      measure: 4,
    }),
    note({
      exportId: "hs-sn-000012-2",
      canonicalId: "sn-000012",
      step: "G",
      octave: 4,
      type: "whole",
      measure: 5,
      tied: true,
    }),
  ];
  const issues: ScoreReviewIssue[] = [
    {
      id: "ri-000001",
      scoreRevision: "rev-x",
      canonicalNoteIds: ["sn-000012"],
      reason: "quantization_ambiguous",
      severity: "caution",
      evidence: { confidence: 0.713 },
      status: "open",
    },
  ];

  it("builds the note-selected model with both presentations", () => {
    const model = buildNoteInspector({
      canonicalId: "sn-000012",
      concert,
      written,
      onsetMs: 7200,
      issues,
      copy,
    });
    expect(model.kind).toBe("note");
    expect(model.canonicalId).toBe("sn-000012");
    expect(model.concertPitch).toBe("C4");
    expect(model.writtenPitch).toBe("G4");
    expect(model.measure).toBe(4);
    expect(model.onsetLabel).toBe("第4小節（スコア 7.2 秒）");
    expect(model.tieLabel).toBe("タイで分割（2分割）");
    expect(model.issues[0]?.reasonTitle).toBe("title:quantization_ambiguous");
    expect(model.issues[0]?.confidencePct).toBe(71);
  });

  it("omits the written row when both presentations spell the same", () => {
    const model = buildNoteInspector({
      canonicalId: "sn-000001",
      concert: [note({ step: "C", octave: 4 })],
      written: [note({ step: "C", octave: 4 })],
      onsetMs: null,
      issues: [],
      copy,
    });
    expect(model.writtenPitch).toBeNull();
    expect(model.tieLabel).toBeNull();
  });

  it("handles rests (no canonical id, no issues)", () => {
    const model = buildNoteInspector({
      canonicalId: null,
      concert: [
        note({ canonicalId: null, isRest: true, exportId: "hs-rest-000001" }),
      ],
      written: [],
      onsetMs: null,
      issues: [],
      copy,
    });
    expect(model.canonicalId).toBeNull();
    expect(model.concertPitch).toBe("");
  });
});

describe("headlinePitch", () => {
  const model = buildNoteInspector({
    canonicalId: "sn-000012",
    concert: [note({ step: "C", octave: 4 })],
    written: [note({ step: "G", octave: 4 })],
    onsetMs: null,
    issues: [],
    copy,
  });

  it("leads with the presentation the user is viewing", () => {
    expect(headlinePitch(model, "concert").primary).toBe("C4");
    expect(headlinePitch(model, "hornF").primary).toBe("G4");
    expect(headlinePitch(model, "hornF").secondary).toBe("C4");
  });
});

describe("keyLabelJa", () => {
  it("maps fifths to Japanese key names", () => {
    expect(keyLabelJa(0)).toBe("ハ長調");
    expect(keyLabelJa(-1)).toBe("ヘ長調");
    expect(keyLabelJa(1)).toBe("ト長調");
    expect(keyLabelJa(42)).toBe("42");
  });
  it("names minor signatures when mode is minor (#252)", () => {
    expect(keyLabelJa(0, "minor")).toBe("イ短調");
    expect(keyLabelJa(-1, "minor")).toBe("ニ短調");
    expect(keyLabelJa(1, "minor")).toBe("ホ短調");
    expect(keyLabelJa(-3, "minor")).toBe("ハ短調");
    expect(keyLabelJa(0, null)).toBe("ハ長調");
  });
});
